package com.himanshu.securepay.service;
import com.himanshu.securepay.dto.*; import com.himanshu.securepay.entity.Payment; import com.himanshu.securepay.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal;
@Service public class PaymentService {
 private final PaymentRepository payments; private final CardTokenRepository tokens; private final BigDecimal fraudThreshold;
 public PaymentService(PaymentRepository payments,CardTokenRepository tokens,@Value("${securepay.fraud-threshold:2500.00}") BigDecimal fraudThreshold){this.payments=payments;this.tokens=tokens;this.fraudThreshold=fraudThreshold;}
 @Transactional public PaymentResponse authorize(String key,AuthorizeRequest req){if(key==null||key.isBlank()||key.length()>100)throw new IllegalArgumentException("Idempotency-Key header is required (max 100 characters)");var existing=payments.findByIdempotencyKey(key);if(existing.isPresent())return toResponse(existing.get());if(!tokens.existsById(req.cardToken()))throw new IllegalArgumentException("Unknown card token");String status="APPROVED",reason=null,code=String.format("%06d",new java.security.SecureRandom().nextInt(1_000_000));if(req.amount().compareTo(fraudThreshold)>0){status="DECLINED";reason="FRAUD_RULE_AMOUNT_THRESHOLD";code=null;}else if(req.amount().compareTo(new BigDecimal("1000.00"))>0){status="DECLINED";reason="INSUFFICIENT_FUNDS_SIMULATION";code=null;}Payment p=payments.save(new Payment(key,req.amount(),req.currency()==null?"GBP":req.currency(),status,reason,code,req.cardToken()));return toResponse(p);}
 public PaymentResponse findById(java.util.UUID id){return payments.findById(id).map(this::toResponse).orElseThrow(()->new IllegalArgumentException("Payment not found"));}
 private PaymentResponse toResponse(Payment p){return new PaymentResponse(p.getId(),p.getStatus(),p.getAuthorizationCode(),p.getDeclineReason(),p.getAmount(),p.getCurrency(),p.getCardToken(),p.getCreatedAt());}
}
